            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == bg):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append(cells)

    out = [row[:] for row in grid]
    if components:
        # The largest connected background region is the open/exterior area;
        # the other isolated regions are enclosed pockets to fill.
        exterior = max(range(len(components)), key=lambda i: len(components[i]))
        for i, cells in enumerate(components):
            if i != exterior:
                for r, c in cells:
                    out[r][c] = 4
