            cells = []
            edges = set()

            while q:
                r, c = q.popleft()
                cells.append((r, c))
                if r == 0:
                    edges.add("top")
                if r == h - 1:
                    edges.add("bottom")
                if c == 0:
                    edges.add("left")
                if c == w - 1:
                    edges.add("right")

                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (0 <= nr < h and 0 <= nc < w and not seen[nr][nc]
                            and grid[nr][nc] == bg):
                        seen[nr][nc] = True
                        q.append((nr, nc))

            # Small pockets enclosed by the lines may use one grid edge as
            # part of their boundary; regions open to multiple edges are exterior.
            if len(edges) <= 1:
                for r, c in cells:
                    out[r][c] = 4

    return out
